    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking the ticket amount as input and optionally extra calls
    function run(uint amount) public payable {
        // must have enough balance to send amount if we will call play
        require(address(this).balance >= amount, "insufficient balance for test");

        // read pre-state
        uint beforePot = c.pot();
        uint beforeBalanceC = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint afterPot = c.pot();
        uint afterBalanceC = address(c).balance;

        // General invariant: If the call reverted, nothing changed in C's observed state;
        // if it did not revert and the sent amount equals TICKET_AMOUNT (10), then the
