        assert( (reverted && afterPot == beforePot && afterBalanceC == beforeBalanceC)
                || (!reverted && amount == 10 &&
                    afterBalanceC + afterPot == beforeBalanceC + beforePot + amount &&
                    (afterPot == beforePot + amount || afterPot == 0)
                   )
              );
    }

    receive() external payable {}
}

