        uint beforeBalanceC = address(c).balance;

        // make the call and capture whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        uint afterPot = c.pot();
        address afterBank = c.bank();
        uint afterBalanceC = address(c).balance;

        // General rule:
        // - If the call reverted, then nothing about pot or bank or balance changed.
        // - If the call did not revert and the sent amount equals C.TICKET_AMOUNT (10), then either
        //     * a payout happened: contract balance equals beforeBalanceC - 1 (fee paid to bank) and pot == 0,
        //       or
        //     * no payout happened: contract balance == beforeBalanceC + 10 and pot == beforePot + 10.
        // - Bank address is unchanged when call does not revert.

        // We cannot reference C.TICKET_AMOUNT constant directly, so enforce using the observed behavior for amount == 10.
        // Use amount==10 as the ticket case (matching the contract's TICKET_AMOUNT).

        if (reverted) {
            assert(afterPot == beforePot && afterBank == beforeBank && afterBalanceC == beforeBalanceC);
        } else {
            // bank must remain the same on successful call
            // (the constructor sets bank and play() never changes it)
            require(afterBank == beforeBank);

            if (amount == 10) {
                // either payout happened: pot reset to 0 and contract lost exactly 1 (fee) compared to before
                bool payoutCase = (afterPot == 0 && afterBalanceC + 1 == beforeBalanceC);
                // or no payout: pot increased by exactly 10 and contract gained 10
