                assert(payoutCase || noPayoutCase);
            } else {
                // if non-ticket amount but did not revert (shouldn't happen), fall back to conservative check:
                // require that pot didn't increase by more than amount and balance change equals pot change
                uint potDelta = afterPot >= beforePot ? afterPot - beforePot : 0;
                uint balanceDelta = afterBalanceC >= beforeBalanceC ? afterBalanceC - beforeBalanceC : 0;
                assert(potDelta <= amount && balanceDelta == potDelta);
            }
        }
    }

    // receive to allow receiving refunds/payouts
