        uint afterBalance = address(c).balance;
        address afterBank = c.bank();

        // General rule:
        // - If amount != 10 then the call must revert and neither pot nor contract balance change.
        // - If amount == 10 and the call reverted then pot and balance unchanged.
        // - If amount == 10 and the call succeeded then bank address unchanged and
        //   either pot increased by 10 (so contract balance increases by 10) or pot became 0
        //   (which corresponds to a payout where contract balance decreases by 1 fee).
        assert(
            // case: wrong amount -> must revert and no state change
            (amount != 10 && reverted && afterPot == beforePot && afterBalance == beforeBalance && afterBank == beforeBank)
            ||
            // case: correct amount but reverted -> no state change
            (amount == 10 && reverted && afterPot == beforePot && afterBalance == beforeBalance && afterBank == beforeBank)
            ||
            // case: correct amount and succeeded -> bank unchanged and either pot increased by 10 and balance increased by 10,
            // or pot reset to 0 and balance decreased by 1 (the fee sent to bank)
            (amount == 10 && !reverted && afterBank == beforeBank && (
                (afterPot == beforePot + 10 && afterBalance == beforeBalance + 10)
                ||
                (afterPot == 0 && afterBalance + 1 == beforeBalance)
            ))
        );
    }

    receive() external payable { }
}
